INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9838157$q$, $q$要聞$q$, $q$慶祝味全龍封王 味全食品優惠方案出爐$q$, $q$<!--0--><p>中華職棒味全龍隊在今天的龍、象之爭以6比0拿下第四勝，奪得年度總冠軍，也是隊史的第六座冠軍獎盃。為慶祝味全龍封王，味全食品宣布推出以下通路優惠活動。</p><!--1--><p>線下通路方面，康達盛通（萬家福／樂家康）、全聯、大全聯實體門市：10/28－10/30期間，購買味全全系列商品，滿399元折50元。$q$, $q$https://money.udn.com//money/story/5648/9838157?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9838157.jpg$q$, ARRAY[$q$味全$q$, $q$全聯$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9838204$q$, $q$要聞$q$, $q$今彩539第115259期開獎$q$, $q$<!--0--><p>今彩539第115259期開獎，中獎號碼19、35、28、13、15。3星彩中獎號碼230，4星彩中獎號碼2714。</p><!--1--><p>實際中獎獎號以台彩公布為準。</p><!--99-->$q$, $q$https://money.udn.com//money/story/122328/9838204?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9838204.jpg$q$, ARRAY[]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9837670$q$, $q$要聞$q$, $q$台灣今年經濟成長率上看12% 國發會提醒後續三大變因$q$, $q$<!--0--><p>AI需求持續推升台灣經濟成長動能。國發會彙整國內外主要機構預測顯示，2026年台灣經濟成長率預估介於10.05%至12%，最高與最低預測值相差1.95個百分點，反映各機構對台灣今年經濟表現雖普遍樂觀，但對後續成長力道仍有不同看法。$q$, $q$https://money.udn.com//money/story/10869/9837670?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9837670.jpg$q$, ARRAY[$q$國發會$q$, $q$花旗$q$, $q$高盛$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9836834$q$, $q$兩岸$q$, $q$陸重卡銷量 電動賣贏燃油 下半場「電電競爭」將開打$q$, $q$<!--0--><p>大陸電動重型卡車（重卡）9月單月滲透率首次突破50%，達50.28%，意味著新能源重卡銷量已超過燃油重卡。電池巨頭寧德時代最近喊出，重卡電動化的下半場，即將進入‌‌「電電競爭」階段，意指電動重卡行業在油電之爭基本結束後，進入不同電動化技術路線比拼新階段。$q$, $q$https://money.udn.com//money/story/5604/9836834?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9836834.jpg$q$, ARRAY[$q$中國$q$, $q$能源$q$, $q$寧德時代$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9836837$q$, $q$兩岸$q$, $q$月之暗面 K3 模型大升級 3兆級參數規模稱冠全球$q$, $q$<!--0--><p>大陸AI初創企業月之暗面（Moonshot AI）發布新一代旗艦模型Kimi K3.1 Pro，為K3模型首次重大升級，該模型為3兆級參數規模，支持100萬詞元上下文視窗，為目前全球參數規模最大的開源模型。$q$, $q$https://money.udn.com//money/story/5604/9836837?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9836837.jpg$q$, ARRAY[]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9838455$q$, $q$期貨$q$, $q$台指期 當心遞延賣壓$q$, $q$<p>台指期上周四（22日）下跌跌741點至46,272點，與現貨正價差達230.57點。法人表示，薔琵颱風、光復節連假休市期間，美股走跌壓力將反映在今日盤面，投資人宜謹慎操作。</p><!--1--><p>而台股開高後震盪走低，早盤一度站上47,300點，但隨後指數翻黑並回測46,000點關卡，上市下跌家數明顯多於上漲家數，終場指數收46,041點，下跌846點，跌破季線支撐，而此次休市期間，美股走跌壓力也將反應在今日盤面上，投資人宜謹慎操作。$q$, $q$https://money.udn.com//money/story/11112/9838455?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9838455.jpg$q$, ARRAY[$q$台指期$q$, $q$選擇權$q$, $q$美股$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9838464$q$, $q$期貨$q$, $q$台指期 順勢操作$q$, $q$<!--0--><p>富邦期貨分析師曹富凱表示，雖美股短線受到AI企業融資等疑慮影響，行情持續拉回，但市場焦點仍圍繞在人工智慧應用擴張、企業獲利展望改善及AI產業需求仍強等題材，在資金可望持續逢低回流下，台股短線在震盪後，中長線後市不看淡。$q$, $q$https://money.udn.com//money/story/11113/9838464?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9838464.jpg$q$, ARRAY[$q$台指期$q$, $q$美股$q$, $q$富邦$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9836458$q$, $q$專題$q$, $q$整理包／0050 市值型 ETF 王位遭挑戰！006208 一拆八搶市 009804、009816 也來了...四檔買誰好？$q$, $q$<p>台股ETF競爭愈來愈激烈，穩坐市值型ETF龍頭的元大台灣50<a class="systex-link" href="https://money.udn.com/industry/company/0050" target="_blank">（0050）</a>，如今面臨多檔ETF搶市！其中，追蹤相同指數的富邦台50（006208），預告將以「一拆八」分割話題吸引投資人目光；另外，還有聯邦台精彩50（009804）主打單一成分股權重上限30%，凱基台灣TOP50（009816）則採不配息設計，各自搶攻不同投資需求。$q$, $q$https://money.udn.com//money/story/124512/9836458?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9836458.jpg$q$, ARRAY[]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9836651$q$, $q$理財$q$, $q$Google 、微軟等上季營收估增雙位數 美科技商品有利可圖$q$, $q$<p>美股超級財報周即將登場，科技巨頭上季財報將成為牽動美股後市的重要風向球。隨人工智慧（AI）投資持續擴張，市場焦點已從科技企業資本支出規模，逐步轉向AI應用商業化與實質獲利貢獻。</p><!--1--><p>根據市場預估，Google、微軟、亞馬遜及蘋果上季營收均有望維持雙位數年增，輝達、博通及美光科技更展現強勁成長潛力，投資人可透過美國科技ETF，掌握美國創新科技產業長期發展契機。$q$, $q$https://money.udn.com//money/story/5618/9836651?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9836651.jpg$q$, ARRAY[$q$博通$q$, $q$微軟$q$, $q$Google$q$]::text[]);
INSERT INTO news (news_id, category, title, content, url, article_image, keywords) VALUES ($q$9837890$q$, $q$國際$q$, $q$周末精選／台股跌夠沒就看這周？晶片業財報掀牌關鍵 48 小時$q$, $q$<p>擔心錯過重要新聞？經濟日報幫您精選周末結束前必看的內容。</p><!--1--><!--2-->$q$, $q$https://money.udn.com//money/story/123398/9837890?from=edn_subcatelist_cate$q$, $q$https://img.test/news/9837890.jpg$q$, ARRAY[]::text[]);
